INSERT INTO feature VALUES('toolchain-switch','tooling','A running language or model server follows a toolchain switch','toolchain-proxy','implemented','ordinary',NULL,'On Unix, `gandr lsp` asks before each frame from its client, while none of the client''s requests waits for its answer, whether the selection names another image of `gandr` than the one running, a rebuild in place among them; when it does, it holds that frame, takes the connection''s replay from its hub — the client''s `initialize`, `initialized`, and a `didOpen` of each document it holds at its text and version — and execs the selected toolchain with the same arguments, which opens a hub of its own build with the replay, drops the answer to the replayed `initialize`, and goes on with the held frame, so the client never restarts. `gandr mcp` follows the same way before each line from its client, its replay the client''s `initialize` and `notifications/initialized`, which the relay keeps itself. A socket named by `--socket` keeps the session where it started.','surface-driver surface-lsp surface-lsp-base surface-agentic','crates/surface-driver/tests/cli.rs crates/surface-lsp/src/hub.rs crates/surface-lsp-base/src/handover.rs crates/surface-agentic/src/face.rs',NULL,'#4377');
